/**
 * Phase 4, plus a way in.
 *
 * Everything under here has been real since Phase 3 — the store, the applier,
 * the view models, the seeded dice, the stage machine. Phase 4 made the last
 * two fakes real: the dungeon is generated by the pipeline rather than read
 * from a fixture, and the referee is the model rather than a keyword table.
 *
 * What is new is the front of the app. A bare load lands on `Characters`, goes
 * to `RunSetup`, and generation starts when the player confirms — rather than
 * on mount, from whatever the URL happened to say.
 *
 * The dev switches still bypass all of that, because interface work against a
 * real dungeon is unbearable if every iteration costs two clicks and a minute:
 *
 *   ?offline=1   the fixture dungeon AND the fixture referee. Spends nothing.
 *   ?stub=1      the Phase 3 referee on a real dungeon. Generation still costs.
 *   ?stub=0      with ?offline=1: the fixture dungeon, the real referee.
 *   ?seed=       which dungeon. Same seed, same dungeon.
 *   ?size=1..5   how big. Each region is one content-pass call.
 *   ?level=      how dangerous.
 *
 * OFFLINE MEANS OFFLINE, and did not always: it used to swap only the
 * generator, so the dungeon was free and then room entry called the model
 * before the player had typed anything. It now implies the stub referee. The
 * reading and the reasoning are in `switches.ts`, which is a pure function of
 * the query string so that the logic can be tested rather than trusted.
 *
 * Any one of those present means: skip the front, generate immediately with
 * the first saved character, exactly as this file behaved before. With none of
 * them, a fresh load costs a minute and real tokens, which is why they exist.
 *
 * Every run writes itself down. The journal goes to `out/runs/<run id>/` by way
 * of the dev server — see the plugin in vite.config.ts — and holds the dungeon,
 * every prompt and response, every roll, and every change to the world.
 */

import { useEffect, useMemo, useState } from "react";
import { PlayScreen } from "./ui/play/PlayScreen.tsx";
import { LoadingScreen } from "./ui/LoadingScreen.tsx";
import { Characters } from "./ui/Characters.tsx";
import { CreateCharacter } from "./ui/create/CreateCharacter.tsx";
import { RunSetup } from "./ui/RunSetup.tsx";
import { toItems } from "./ui/play/Narration.tsx";
import { useGame } from "./store/react.ts";
import { deleteCharacter, listCharacters, saveCharacter } from "./store/characters.ts";
import {
  createGameSession,
  describeFailure,
  type PlayableSession,
  type RunRequest,
} from "./runtime/session.ts";
import { createRemoteSession } from "./runtime/remote-session.ts";
import { type GenerationProgress } from "./runtime/generate.ts";
import { stubReferee } from "./runtime/__fixtures__/stub-referee.ts";
import { generateOffline, testCharacter } from "./runtime/__fixtures__/offline.ts";
import { randomSeed } from "./runtime/seeds.ts";
import { readSwitches } from "./switches.ts";
import type { PlayerCharacter } from "./engine/index.ts";

const {
  offline: OFFLINE,
  stub: STUB,
  bypass: BYPASS,
  seed: SEED,
  pinnedSeed: PINNED,
  size: SIZE,
  level: LEVEL,
} = readSwitches(location.search);

/**
 * A run started from the front of the app gets a fresh dungeon unless the URL
 * pinned one. The bypass path keeps its 1005 default, so `?stub=1` on its own
 * still returns to the same dungeon every time — which is the whole point of
 * it during interface work.
 */
const seedForNewRun = () => (PINNED ? SEED : randomSeed());

/**
 * The switches that mean "do not touch the server".
 *
 * Either one keeps the whole run in the browser. `?stub` still generates for
 * real, which is a model call — but it is one this page makes through the API
 * only when it is NOT local, and locally it has no key to make it with. So a
 * local run means a local dungeon too: `?stub` alone is `?stub` plus the
 * fixture, which is what it always effectively was during interface work.
 */
const LOCAL = OFFLINE || STUB;

/**
 * The dev quick-start character.
 *
 * It used to be seeded into `store/characters.ts`, which is a database now —
 * and handing every visitor somebody called Testy with +3 in everything is a
 * different proposition from handing one to a developer with `?offline` in the
 * URL. So the fixture lives with the fixtures and appears only on a local run.
 */
const localCharacters = () => [testCharacter()];

/** Only the part before a run. Once the dungeon exists, that is what decides. */
type Screen = "characters" | "create" | "setup" | "generating";

export default function App() {
  const [progress, setProgress] = useState<GenerationProgress>();

  /**
   * A session, and which KIND of session, decided here and nowhere else.
   *
   * A real run is played by the server: this holds a store, posts what the
   * player did, and shows what came back. `?offline` and `?stub` are played in
   * the browser, exactly as they were before there was a server — that is the
   * whole point of them. Interface work should not need Postgres running, and a
   * fixture dungeon refereed by a keyword table costs nothing and answers
   * instantly.
   *
   * Both satisfy `PlayableSession`, so everything below this line is the same
   * either way.
   */
  const makeSession = (): PlayableSession =>
    LOCAL
      ? createGameSession({
          onProgress: setProgress,
          ...(STUB ? { referee: () => stubReferee } : {}),
          ...(OFFLINE
            ? { offline: true, generate: async ({ seed, size }) => generateOffline(seed, size) }
            : {}),
        })
      : createRemoteSession({ onProgress: setProgress });

  /**
   * The run in hand. Made on the first render — so the store it owns is there
   * to subscribe to before there is a dungeon in it — and replaced only when a
   * failed generation is retried, because a session that has begun refuses to
   * begin again and a half-generated one is not worth resuming.
   *
   * State rather than a ref, because swapping it has to re-render: the
   * subscription below is to *this* store, and the play screen has to follow
   * the new one.
   */
  const [session, setSession] = useState<PlayableSession>(makeSession);

  const { dungeon, run } = useGame(session.store);
  const [screen, setScreen] = useState<Screen>(BYPASS ? "generating" : "characters");
  const [characters, setCharacters] = useState<PlayerCharacter[]>();
  /** Whoever the player pressed *Send down* on, carried into run setup. */
  const [chosenId, setChosenId] = useState<string>();
  const [error, setError] = useState<string>();
  /** Held so a failed generation can be tried again on the same seed. */
  const [lastRequest, setLastRequest] = useState<RunRequest>();

  async function start(s: PlayableSession, request: RunRequest) {
    setScreen("generating");
    try {
      // A second call on the SAME session is the double-invoke of StrictMode's
      // development mount, and the session drops it — it would otherwise
      // generate a whole second dungeon over the top of the first.
      await s.begin(request);
    } catch (e) {
      // `describeFailure` puts the first few validation complaints into the
      // sentence. The whole error is already on the console and in the journal;
      // this is the part that fits on a screen.
      setError(describeFailure(e));
    }
  }

  async function begin(request: RunRequest) {
    setLastRequest(request);
    await start(session, request);
  }

  /**
   * Try the same seed again, on a session of its own.
   *
   * The same seed on purpose: a generation that failed once usually succeeds on
   * the second attempt — the failure is a model having a bad round rather than
   * a dungeon that cannot be built — and if it fails twice on the same seed
   * that is worth knowing, which a fresh random seed would hide.
   */
  function retryGeneration() {
    if (!lastRequest) return;
    const next = makeSession();
    setSession(next);
    setError(undefined);
    setProgress(undefined);
    void start(next, lastRequest);
  }

  useEffect(() => {
    void (async () => {
      const cs = LOCAL ? localCharacters() : await listCharacters();
      setCharacters(cs);
      if (BYPASS && cs[0]) {
        void begin({ seed: SEED, size: SIZE, level: LEVEL, character: cs[0] });
      }
    })();
  }, []);

  const items = useMemo(() => {
    if (!run) return [];
    const name = (id: string) => run.entities.rooms.find((r) => r.id === id)?.name ?? "Somewhere";
    const pass = session.store.getState().dungeon?.pass;
    return toItems(run.log, name, pass && { name: pass.name, objective: pass.goal.summary });
  }, [run?.log]);

  if (error) {
    return (
      <div className="p-8 font-mono text-sm text-torch space-y-4 max-w-3xl">
        <p>Could not build a dungeon: {error}</p>
        {/* Locally the journal is a directory, and without the id on the
            screen the only way to find it is by guessing at the timestamp. A
            remote run has no directory: its journal is in the database, and a
            generation that failed has no run row to point at yet either. */}
        <p className="text-ash">
          The whole failure is on the console
          {session.runId ? `, and in out/runs/${session.runId}/` : ""}
        </p>
        {lastRequest && (
          <button
            type="button"
            className="border border-torch px-3 py-1 hover:bg-torch hover:text-ink"
            onClick={retryGeneration}
          >
            Try seed {lastRequest.seed} again
          </button>
        )}
      </div>
    );
  }

  if (screen === "characters") {
    return (
      <Characters
        characters={characters}
        onStartRun={(pc) => {
          setChosenId(pc.id);
          setScreen("setup");
        }}
        onCreate={() => setScreen("create")}
        onDelete={(pc) =>
          void (async () => {
            await deleteCharacter(pc.id);
            setCharacters(await listCharacters());
          })()
        }
      />
    );
  }

  if (screen === "create") {
    return (
      <CreateCharacter
        onCancel={() => setScreen("characters")}
        onSave={(pc) =>
          void (async () => {
            await saveCharacter(pc);
            setCharacters(await listCharacters());
            setChosenId(pc.id);
            setScreen("characters");
          })()
        }
      />
    );
  }

  if (screen === "setup") {
    return (
      <RunSetup
        characters={characters ?? []}
        initialId={chosenId}
        onBack={() => setScreen("characters")}
        onConfirm={({ size, level, character }) =>
          void begin({ seed: seedForNewRun(), size, level, character })
        }
      />
    );
  }

  if (!dungeon || !run) {
    return <LoadingScreen progress={progress} />;
  }

  return (
    <PlayScreen
      dungeon={dungeon}
      run={run}
      items={items}
      onSubmit={(text) => void session.submit(text)}
      onRoll={() => void session.roll()}
      onRetry={() => void session.retry()}
    />
  );
}
